{
  "type": "object",
  "properties": {
    "Date of meeting": { "type": "string", "description": "ISO date YYYY-MM-DD" },
    "Time of meeting": { "type": "string", "description": "e.g. 1:00 PM" },
    "Time zone": { "type": "string" },
    "Duration of meeting": { "type": "string" }
  },
  "required": []
}

options.systemMessage:
=This is an email asking if alex can attend an event or a meeting. the date and time of the meeting are very specific in the email. Extract the date, time, time zone and duration of the meeting from the email. 

BE VERY CAREFUL TO CHOOSE REAL DATES. LOOK AT {{ $now.format('yyyy-MM-dd') }}
to ensure the date is real (e.g., don't say Sunday January 5th when January 5th is a Monday). 
{{ $now.format('yyyy-MM-dd') }} {{ $now.toISO() }}

parameters.jsCode:
// Resolve the LLM-extracted meeting (date + time + tz + duration text) to a
// FIXED [start,end] instant in epoch ms. DETERMINISTIC — no LLM.
// Replaces the old flow where an LLM judged conflicts over prose fields.
//
// Inputs (from 'Extracted Fields'):
//   meetingDate (YYYY-MM-DD), meetingTime (e.g. "1:00 PM"),
//   meetingTimeZone (e.g. "America/New_York" or "ET"), meetingDuration (prose).
// Output: same fields + meetingStartMs, meetingEndMs, meetingDayStartISO,
//   meetingDayEndISO, meetingTz, meetingResolveError (null on success).
//
// luxon DateTime is a Code-node global in n8n; used for tz-correct parsing.

function safeGet(nodeName) {
  try { return $(nodeName).item.json || {}; } catch (e) { return {}; }
}
const ex = safeGet('Extracted Fields');

const rawDate = (ex.meetingDate || '').trim();
const rawTime = (ex.meetingTime || '').trim();
const rawTz = (ex.meetingTimeZone || '').trim();
const rawDur = (ex.meetingDuration || '').trim();

// --- Timezone normalization (default America/New_York) ---
const TZ_MAP = {
  'ET': 'America/New_York', 'EST': 'America/New_York', 'EDT': 'America/New_York',
  'ETZ': 'America/New_York', 'EASTERN': 'America/New_York',
  'CT': 'America/Chicago', 'CST': 'America/Chicago', 'CDT': 'America/Chicago',
  'MT': 'America/Denver', 'MST': 'America/Denver', 'MDT': 'America/Denver',
  'PT': 'America/Los_Angeles', 'PST': 'America/Los_Angeles', 'PDT': 'America/Los_Angeles',
  'GMT': 'UTC', 'UTC': 'UTC'
};
let tz = 'America/New_York';
if (rawTz) {
  const key = rawTz.toUpperCase().replace(/\s+/g, '');
  if (TZ_MAP[key]) tz = TZ_MAP[key];
  else if (/^[A-Za-z]+\/[A-Za-z_]+/.test(rawTz)) tz = rawTz; // already an IANA zone
}

// --- Duration text -> minutes (default 30) ---
function parseDurationMinutes(text) {
  if (!text) return 30;
  const t = text.toLowerCase();
  let mins = 0, matched = false;
  const hourMatch = t.match(/(\d+(?:\.\d+)?)\s*(?:h|hr|hrs|hour|hours)/);
  if (hourMatch) { mins += Math.round(parseFloat(hourMatch[1]) * 60); matched = true; }
  const minMatch = t.match(/(\d+)\s*(?:m|min|mins|minute|minutes)/);
  if (minMatch) { mins += parseInt(minMatch[1], 10); matched = true; }
  if (!matched) {
    // bare number -> assume minutes if <= 8 assume hours only when "hour" absent
    const bare = t.match(/(\d+(?:\.\d+)?)/);
    if (bare) {
      const n = parseFloat(bare[1]);
      mins = (n > 0 && n <= 8 && /hour|hr/.test(t)) ? Math.round(n * 60) : Math.round(n);
    }
  }
  if (!mins || mins <= 0) mins = 30;
  return mins;
}
const durationMinutes = parseDurationMinutes(rawDur);

// --- Time text -> {hour, minute} (24h) ---
function parseClock(text) {
  if (!text) return null;
  const t = text.trim().toLowerCase();
  const m = t.match(/(\d{1,2})(?::(\d{2}))?\s*(am|pm)?/);
  if (!m) return null;
  let hour = parseInt(m[1], 10);
  const minute = m[2] ? parseInt(m[2], 10) : 0;
  const ap = m[3];
  if (ap === 'pm' && hour < 12) hour += 12;
  if (ap === 'am' && hour === 12) hour = 0;
  if (hour < 0 || hour > 23 || minute < 0 || minute > 59) return null;
  return { hour, minute };
}

let meetingStartMs = null, meetingEndMs = null, err = null;
let dayStartISO = '', dayEndISO = '';

if (!rawDate || !/^\d{4}-\d{2}-\d{2}$/.test(rawDate)) {
  err = `Missing/invalid meeting date: "${rawDate}"`;
} else {
  const clock = parseClock(rawTime);
  // Day bounds for the calendar filter (always computable from the date).
  try {
    const dayStart = DateTime.fromISO(rawDate, { zone: tz }).startOf('day');
    const dayEnd = DateTime.fromISO(rawDate, { zone: tz }).endOf('day');
    dayStartISO = dayStart.toISO();
    dayEndISO = dayEnd.toISO();
  } catch (e) { err = `Bad date parse: ${e.message}`; }

  if (!err && !clock) {
    err = `Missing/invalid meeting time: "${rawTime}"`;
  } else if (!err) {
    const start = DateTime.fromObject(
      { year: +rawDate.slice(0, 4), month: +rawDate.slice(5, 7), day: +rawDate.slice(8, 10),
        hour: clock.hour, minute: clock.minute },
      { zone: tz }
    );
    if (!start.isValid) {
      err = `Invalid instant: ${start.invalidReason || 'unknown'}`;
    } else {
      meetingStartMs = start.toMillis();
      meetingEndMs = start.plus({ minutes: durationMinutes }).toMillis();
    }
  }
}

return [{
  json: {
    ...ex,
    meetingTz: tz,
    durationMinutes,
    meetingStartMs,
    meetingEndMs,
    meetingDayStartISO: dayStartISO,
    meetingDayEndISO: dayEndISO,
    meetingResolveError: err
  }
}];

// DETERMINISTIC conflict check — replaces the LLM "Check for Conflicts" step.
// Filters the day's events to REAL busy time, then tests overlap against the
// resolved meeting instant on epoch ms. Templates the EXACT Relay output
// strings ("Alex is free..." / "Alex has a conflict...") + an idempotency stamp.
//
// Input: aggregated day events on $json.data (from 'Aggregate Busy Events'),
//        resolved instant fields from 'Resolve Meeting Instant'.

function safeGet(nodeName) {
  try { return $(nodeName).item.json || {}; } catch (e) { return {}; }
}
const res = safeGet('Resolve Meeting Instant');

// Aggregate node puts the array on $json.data; fall back to $input.all().
let events = [];
try {
  if (Array.isArray($json.data)) events = $json.data;
  else events = $input.all().map(i => i.json).filter(Boolean);
} catch (e) { events = []; }

const meetingStart = res.meetingStartMs;
const meetingEnd = res.meetingEndMs;
const tz = res.meetingTz || 'America/New_York';
const invitee = 'alex@ahbadvisors.com';

// Reclaim / decompress / task-detail noise (matches 2d idiom).
const RECLAIM_A = 'This AI-powered event was created by Reclaim.ai';
const RECLAIM_B = 'This event was created by Reclaim';
const TASK_DETAIL = "Only you can see this Task's event details. It will show as busy to others and automatically reschedule if booked over.";

function fmt(dt) {
  try {
    return DateTime.fromISO(dt, { zone: tz }).toFormat('h:mm a');
  } catch (e) {
    try { return new Date(dt).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true }); }
    catch (e2) { return String(dt || ''); }
  }
}

// If we couldn't resolve the meeting to an instant, fail soft: report it,
// don't fabricate a "free" answer.
const stampISO = DateTime.now().setZone(tz).toISO();
const checkedDate = res.meetingDate || '';

if (res.meetingResolveError || meetingStart == null || meetingEnd == null) {
  const msg = `Could not verify Alex's availability automatically (${res.meetingResolveError || 'unresolved meeting time'}). Please check the calendar manually.`;
  return [{
    json: {
      isFree: false,
      resolveFailed: true,
      resultText: `${msg}\n\n_Checked ${checkedDate} at ${stampISO}_`,
      conflicts: [],
      checkedDate,
      checkedAt: stampISO
    }
  }];
}

const conflicts = [];
for (const ev of events) {
  if (!ev) continue;
  const transparency = ev.transparency || 'opaque';
  const status = ev.status || 'confirmed';
  const desc = ev.description || '';
  const title = ev.summary || '(no title)';

  // Exclude non-busy / cancelled.
  if (transparency === 'transparent') continue;          // "Free" events
  if (status === 'cancelled') continue;

  // Exclude the invitee's own DECLINED attendance.
  let declined = false;
  const attendees = ev.attendees || [];
  for (const a of attendees) {
    const email = (a.email || '').toLowerCase();
    if ((email === invitee || a.self === true) && a.responseStatus === 'declined') { declined = true; break; }
  }
  if (declined) continue;

  // Exclude Reclaim / decompress / task-detail noise.
  if (desc.includes(RECLAIM_A)) continue;
  if (desc.includes(RECLAIM_B)) continue;
  if (desc.includes(TASK_DETAIL)) continue;
  if (title.toLowerCase().includes('decompress')) continue;

  // All-day events: start.date (no time) -> NOT a hard block. Skip.
  const isAllDay = !!(ev.start && ev.start.date && !ev.start.dateTime);
  if (isAllDay) continue;

  const evStartISO = (ev.start && (ev.start.dateTime || ev.start.date)) || '';
  const evEndISO = (ev.end && (ev.end.dateTime || ev.end.date)) || '';
  const evStart = evStartISO ? new Date(evStartISO).getTime() : NaN;
  const evEnd = evEndISO ? new Date(evEndISO).getTime() : NaN;
  if (isNaN(evStart) || isNaN(evEnd)) continue;

  // Deterministic overlap: evStart < meetingEnd && evEnd > meetingStart.
  if (evStart < meetingEnd && evEnd > meetingStart) {
    const guests = attendees
      .map(a => a.displayName || a.email || '')
      .filter(g => g && g.toLowerCase() !== invitee)
      .join(', ');
    conflicts.push({
      title,
      startFmt: fmt(evStartISO),
      endFmt: fmt(evEndISO),
      guests
    });
  }
}

let resultText;
let isFree;
if (conflicts.length === 0) {
  isFree = true;
  resultText = 'Alex is free for this meeting.';
} else {
  isFree = false;
  const c = conflicts[0];
  const guestClause = c.guests ? ` with ${c.guests}` : '';
  resultText = `Alex has a conflict: ${c.title} from ${c.startFmt} to ${c.endFmt}${guestClause}.`;
  if (conflicts.length > 1) {
    const extra = conflicts.slice(1)
      .map(x => `- ${x.title} from ${x.startFmt} to ${x.endFmt}${x.guests ? ' with ' + x.guests : ''}`)
      .join('\n');
    resultText += `\n\nAlso overlapping:\n${extra}`;
  }
}

// Idempotency stamp: a re-added label producing a duplicate comment is
// human-detectable by the checked-date + timestamp line.
resultText += `\n\n_Checked ${checkedDate} at ${stampISO}_`;

return [{
  json: {
    isFree,
    resolveFailed: false,
    resultText,
    conflicts,
    conflictCount: conflicts.length,
    checkedDate,
    checkedAt: stampISO
  }
}];
